#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    for (char& c : s)
        if (c == '0')
            c = '1';
        else
            c = '0';

    cout << s << endl;

    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    string s;
    cin >> s;

    replace(s.begin(), s.end(), '0', 'x');
    replace(s.begin(), s.end(), '1', '0');
    replace(s.begin(), s.end(), 'x', '1');

    cout << s << endl;

    return 0;
}
